contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into C; always perform deposit, then attempt withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit into c from this contract (top-level state-changing call)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record balances immediately after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // attempt withdrawAll as a top-level try/catch statement
        bool withdrewReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        // balances after possible withdraw
        uint afterAllThis = address(this).balance;
        uint afterAllC = address(c).balance;

        // General rule: either successful withdraw returns exactly depositAmount to this contract
        // and reduces C's balance by depositAmount (relative to after-deposit),
        // or withdraw reverted and both balances stayed equal to their after-deposit values.
        assert(
            (!withdrewReverted && afterAllThis == afterDepositThis + depositAmount && afterAllC + depositAmount == afterDepositC)
            || (withdrewReverted && afterAllThis == afterDepositThis && afterAllC == afterDepositC)
        );
    }

    receive() external payable { }
}

