// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint afterAllThis = address(this).balance;
        uint afterAllC = address(c).balance;
        assertTrue((!withdrewReverted && afterAllThis == afterDepositThis + depositAmount && afterAllC + depositAmount == afterDepositC)
            || (withdrewReverted && afterAllThis == afterDepositThis && afterAllC == afterDepositC));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable { }
}
